// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address caller, address newDao) public {
        vm.assume(caller != address(0));
        vm.assume(newDao != address(0));

        // Configure the contract and set an initial DAO that is different from caller
        address initialDao = address(0xdead);
        vm.assume(caller != initialDao);
        c.setDAO(initialDao);
        c.endConfiguration();

        address preDao = c.DAO();

        vm.prank(caller);
        try c.setDAO(newDao) {
            // Call should not succeed on reference
            assertTrue(false, "setDAO should revert on reference");
        } catch {
            // Expected path on reference: DAO unchanged
        }

        assertTrue(c.DAO() == preDao, "DAO changed by unauthorized caller on reference");
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
